import java.time.Duration;
import java.time.Instant;
import java.time.LocalDate;
import java.time.LocalDateTime;
import java.time.LocalTime;
import java.time.OffsetDateTime;
import java.time.Period;
import java.time.ZoneId;
import java.time.ZoneOffset;
import java.time.ZonedDateTime;
import java.time.format.DateTimeFormatter;
import java.util.Date;

public class Main {
    // DateTimeFormatter 不可变、线程安全，作为常量复用
    private static final DateTimeFormatter API_TIME = DateTimeFormatter.ISO_OFFSET_DATE_TIME;

    public static void main(String[] args) {
        // ---- 1. 按语义选类型 ----
        LocalDate billDate = LocalDate.of(2026, 6, 18);       // 纯日期：账单日
        LocalTime storeOpen = LocalTime.of(9, 0);             // 纯时间：开门时间
        LocalDateTime meetingLocal = LocalDateTime.of(2026, 6, 18, 10, 30); // 本地日历时间

        // ---- 2. 本地时间 → 全球瞬间 → 存储 ----
        ZoneId shanghai = ZoneId.of("Asia/Shanghai");
        ZonedDateTime meetingInShanghai = meetingLocal.atZone(shanghai); // 绑定时区
        Instant auditTime = meetingInShanghai.toInstant();               // 转 UTC 时间点
        OffsetDateTime apiTime = auditTime.atOffset(ZoneOffset.UTC);     // 接口传输用 offset
        String text = apiTime.format(API_TIME);                          // "2026-06-18T02:30:00Z"
        OffsetDateTime parsed = OffsetDateTime.parse(text, API_TIME);    // 反序列化

        // ---- 3. 与旧 Date 互转 ----
        Date legacyDate = Date.from(auditTime);
        Instant back = legacyDate.toInstant();

        // ---- 4. DST gap：2026-03-08 02:30 在纽约不存在 ----
        ZoneId newYork = ZoneId.of("America/New_York");
        LocalDateTime gapLocal = LocalDateTime.of(2026, 3, 8, 2, 30);
        ZonedDateTime resolvedGap = gapLocal.atZone(newYork); // 顺延到 03:30 EDT

        // ---- 5. DST overlap：2026-11-01 01:30 在纽约出现两次 ----
        LocalDateTime overlapLocal = LocalDateTime.of(2026, 11, 1, 1, 30);
        ZonedDateTime earlierOffset = overlapLocal.atZone(newYork); // 默认选 offset 较大的 EDT(-4)
        ZonedDateTime laterOffset = earlierOffset.withLaterOffsetAtOverlap(); // 切换到 EST(-5)

        // ---- 6. Period vs Duration 跨 DST 差异 ----
        ZonedDateTime beforeDST = ZonedDateTime.of(2026, 3, 8, 1, 30, 0, 0, newYork);
        ZonedDateTime plusCalendarDay = beforeDST.plus(Period.ofDays(1));   // 日历加一天
        ZonedDateTime plusTwentyFourHours = beforeDST.plus(Duration.ofHours(24)); // 机器加24小时
        long periodHours = Duration.between(beforeDST.toInstant(), plusCalendarDay.toInstant()).toHours();   // 23
        long durationHours = Duration.between(beforeDST.toInstant(), plusTwentyFourHours.toInstant()).toHours(); // 24

        System.out.println("bill/open: " + billDate + " " + storeOpen);
        System.out.println("meeting instant: " + auditTime);
        System.out.println("api text: " + text);
        System.out.println("NY gap resolved: " + resolvedGap);
        System.out.println("NY overlap: " + earlierOffset.getOffset() + " vs " + laterOffset.getOffset());
        System.out.println("Period day = " + periodHours + "h, Duration 24h = " + durationHours + "h");

        assert billDate.equals(LocalDate.of(2026, 6, 18));
        assert storeOpen.equals(LocalTime.of(9, 0));
        assert auditTime.equals(Instant.parse("2026-06-18T02:30:00Z"));
        assert parsed.toInstant().equals(auditTime);
        assert back.equals(auditTime);
        assert resolvedGap.getHour() == 3 && resolvedGap.getMinute() == 30; // gap 顺延
        assert earlierOffset.getOffset().equals(ZoneOffset.ofHours(-4)); // EDT
        assert laterOffset.getOffset().equals(ZoneOffset.ofHours(-5));   // EST
        assert Duration.between(earlierOffset.toInstant(), laterOffset.toInstant()).equals(Duration.ofHours(1));
        assert periodHours == 23;    // 跨 DST 日历一天实际只有 23 小时
        assert durationHours == 24;  // Duration 固定 24 小时
    }
}
